insert into knowledge_chunks (source_file, content, embedding) values ($kc$aqi_categories_health_risk.txt$kc$, $kc$India's AQI considers six pollutants: PM2.5, PM10, NO2, SO2, CO, and O3. The index is calculated separately for each pollutant using a piecewise linear interpolation between defined concentration breakpoints and corresponding index values. The overall AQI is the maximum of all individual sub-indices (the pollutant with the worst relative performance drives the final AQI).$kc$, '[-0.014640,-0.026602,0.026538,-0.030142,0.014800,0.032035,0.088611,0.018354,-0.006304,0.007355,0.006604,-0.095074,0.025938,0.043688,0.009491,-0.001737,0.007923,-0.017153,-0.041427,0.010854,0.064975,-0.001968,-0.042720,-0.092385,0.016059,0.074515,-0.041551,-0.055127,-0.032256,-0.212902,0.005484,-0.021480,0.102095,0.002158,-0.041174,-0.050009,-0.005211,0.058396,-0.019159,0.008849,0.002170,-0.001091,0.020690,-0.058637,-0.049018,-0.057646,-0.017047,0.005807,0.040059,-0.089006,0.023372,-0.005753,-0.030924,0.034219,0.010460,-0.024210,0.066476,0.031782,0.007006,0.029332,0.011851,0.042755,-0.211802,0.066112,0.063756,0.031726,-0.026356,-0.017046,0.003073,0.027870,-0.053917,0.034191,0.042151,0.023256,0.009482,0.005875,-0.036665,-0.007955,-0.014244,-0.006443,-0.019675,-0.034356,-0.025494,-0.022957,0.062668,-0.013705,0.016932,-0.031052,0.041864,0.023241,-0.002298,-0.036662,0.001236,0.014834,-0.028492,-0.009309,0.029815,-0.005145,-0.033583,0.222315,-0.070950,-0.032857,0.006216,-0.009964,-0.006427,-0.048346,-0.037238,-0.082620,0.028016,0.011694,0.000060,0.002417,0.035096,-0.088587,0.010432,-0.004511,0.064452,0.010871,-0.026406,0.020947,-0.015845,0.030552,0.039148,0.009902,0.069051,-0.039090,0.023926,0.104101,-0.018308,0.077922,0.055168,-0.031413,-0.045159,-0.013348,0.017191,-0.036200,0.035093,0.012082,-0.003237,-0.004227,-0.037843,-0.056064,0.026029,-0.124019,-0.027167,0.155139,-0.024725,-0.010868,-0.039490,-0.015435,-0.020187,0.075363,-0.049870,-0.008822,0.058326,0.085657,-0.006743,0.026985,-