insert into knowledge_chunks (source_file, content, embedding) values ($kc$aqi_categories_health_risk.txt$kc$, $kc$India CPCB AQI categories and their health implications:
- 0–50 (Good): Air quality is satisfactory. Little or no risk.
- 51–100 (Satisfactory): Minor breathing discomfort to sensitive people (asthmatics, elderly, children).
- 101–200 (Moderate): Breathing discomfort to those with lung disease, heart disease, and children. Sensitive people should avoid prolonged outdoor exertion.
- 201–300 (Poor): Breathing discomfort to most people on prolonged outdoor exposure. Sensitive groups should avoid outdoor activity.
- 301–400 (Very Poor): Respiratory illness in people on prolonged outdoor exposure. People with heart or lung disease, children, elderly should avoid outdoor exertion entirely.
- 401–500 (Severe/Hazardous): Serious risk to all. Even healthy people should avoid all outdoor activity.$kc$, '[-0.012721,0.013782,0.038145,0.006955,-0.009558,0.047372,0.099119,0.026893,-0.039479,0.039215,0.000251,-0.072791,0.048272,0.058915,0.024188,0.032490,0.050208,0.001692,-0.046532,0.065407,0.011950,0.015700,0.039879,-0.086543,0.026627,0.038433,-0.024352,-0.044917,-0.020842,-0.161878,-0.017856,-0.034990,0.083233,-0.015830,-0.008095,-0.047246,-0.028042,0.036336,-0.030109,0.045791,-0.013487,0.009928,0.051379,-0.052551,-0.048429,-0.044617,-0.064231,-0.007131,0.008890,-0.061519,0.019458,-0.048683,-0.021900,0.056946,-0.012942,-0.001129,0.054365,0.022243,0.026979,0.026388,0.027662,0.050361,-0.194422,0.064142,0.067999,0.017234,-0.016657,-0.024034,0.044313,0.015333,-0.059571,0.040626,0.025524,0.041333,-0.000919,0.020155,-0.053850,-0.029877,-0.006112,0.004458,-0.002253,-0.022735,-0.037818,0.005428,0.002747,-0.034015,0.025442,-0.052458,0.001198,0.012237,0.018093,-0.045958,-0.025563,0.048371,-0.020389,-0.001429,0.041353,0.007134,-0.097682,0.220729,-0.052682,-0.001338,-0.018780,0.009292,0.014970,-0.042001,-0.026951,-0.061054,0.014311,-0.015210,0.017896,-0.006260,0.043837,-0.026894,-0.001085,0.036520,0.051441,0.035859,-0.019753,0.017633,-0.028923,0.002686,0.046540,-0.010796,0.038724,-0.081669,0.017202,0.103936,0.027828,0.061699,0.094371,-0.056517,-0.020215,-0.015457,-0.005967,-0.014663,0.056228,0.036320,0.000570,-0.015980,-0.007940,-0.110561,0.019404,-0.155234,-0.056188,0.088906,-0.030781,0.005743,-0.055349,-0.046475,0.000612,0.047586,-0.036309,-0.019302,0.047903,0.015344,0.022620,0.046494,0.004443,0.001111,0.017476,-0.056029,-0.042636,0.122446,0.034652,-0.031938,-0.056253,-0.004609,-0.007229,-0.000751,0.050229,-0.002292,-0.010610,0.029944,0.068322,0.021785,-0.028800,0.037178,-0.005407,0.019861,0.046683,-0.022642,-0.028723,0.021741,0.027767,-0.030789,-0.052502,-0.011087,0.065803,0.028327,-0.084977,-0.010287,-0.083089,0.017133,-0.021737,-0.018486,-0.043290,-0.041700,0.05033