insert into knowledge_chunks (source_file, content, embedding) values ($kc$aqi_categories_health_risk.txt$kc$, $kc$For agriculture workers, any AQI above 200 (Poor) represents a meaningful occupational health risk during extended outdoor work, particularly for tasks involving physical exertion such as harvesting, ploughing, or pesticide spraying. At AQI above 300, even short-duration outdoor agricultural work carries significant respiratory health risk, and protective equipment (N95 masks rated for particulate filtration) is advisable.$kc$, '[-0.041236,-0.001494,0.026332,0.011683,0.042194,0.024446,0.091622,0.011975,-0.017719,0.009207,-0.009078,-0.085730,0.039689,0.065773,-0.010976,0.020551,0.014520,0.010270,-0.034590,0.023211,0.024535,0.024174,0.005846,-0.070115,0.032941,0.046569,-0.046935,-0.018292,-0.038479,-0.148482,-0.033629,-0.018480,0.068165,0.013841,0.012430,-0.047567,-0.007385,0.046163,0.000871,0.036488,0.028986,-0.002125,0.001435,-0.043133,-0.057870,-0.048658,-0.044288,-0.050702,0.045843,-0.075631,0.015842,-0.044779,0.008143,0.056151,0.030182,-0.025378,0.059423,0.053275,-0.007231,0.017887,0.015043,0.009974,-0.205284,0.061570,0.069668,0.031956,-0.053482,-0.025439,-0.000314,-0.019476,-0.061039,0.036683,-0.009256,0.032474,0.012195,0.020146,-0.033020,-0.073309,0.002894,0.028453,0.017018,-0.025577,-0.044686,0.000621,-0.008722,-0.027048,0.006470,-0.052287,0.083472,-0.005309,-0.011641,-0.037025,-0.053757,0.015241,-0.013541,-0.011826,0.030087,-0.008134,-0.129155,0.255432,-0.067295,-0.012594,-0.014136,-0.036724,0.006702,-0.023333,-0.044682,-0.053802,0.000092,0.031984,0.022784,0.009976,0.018400,-0.031971,0.012599,0.027136,0.035620,0.020545,-0.038060,0.030489,-0.003103,0.036503,0.017302,-0.027794,0.038611,-0.067788,0.057732,0.125034,0.041981,0.078539,0.074082,-0.059412,0.005390,-0.006540,0.007104,0.007106,0.029787,0.051980,-0.009593,-0.011010,-0.041370,-0.104160,0.000334,-0.119647,-0.024832,0.099347,-0.032873,0.018271,-0.058644,-0.044553,-0.024296,0.076687,0.004028,0.