insert into knowledge_chunks (source_file, content, embedding) values ($kc$heat_stress_crop_thresholds.txt$kc$, $kc$Reference: IPCC AR6 WGII Chapter 5 (Food, Fibre, Ecosystem Products), Lobell et al. heat stress crop research

Heat stress in crops occurs when temperatures exceed the physiological optimum during critical growth stages, particularly flowering and grain fill. Even a few days of extreme heat at the right moment can devastate yield disproportionately to what season-average temperatures would predict.$kc$, '[-0.022011,0.001916,0.079623,-0.015061,0.081935,0.030074,0.047582,-0.005282,-0.009201,-0.035553,-0.032904,-0.093756,0.043343,0.056580,0.013685,0.009826,0.015333,0.019693,-0.037724,0.014508,0.071759,0.001813,-0.037921,-0.068142,0.017172,0.041473,-0.060698,-0.008614,-0.060709,-0.189275,0.026812,0.041317,0.052599,-0.014955,-0.012383,-0.058680,-0.008228,0.016956,-0.026533,0.043245,0.058964,-0.030784,-0.023595,-0.052144,-0.030449,-0.054942,-0.012406,-0.006748,0.042089,-0.026254,-0.008665,-0.058631,0.047182,0.015561,0.015141,0.032155,0.071988,0.061846,0.046502,0.025761,0.006351,0.029459,-0.206007,0.025994,0.088349,0.009080,-0.035355,-0.025701,0.006978,-0.001198,-0.037485,0.052400,0.016663,0.065581,0.048123,-0.015419,-0.004304,-0.068703,0.050889,0.012468,0.025558,-0.009775,-0.048039,-0.017142,-0.014548,-0.106695,0.014029,-0.064498,0.049769,-0.023437,-0.047760,-0.075136,-0.044686,-0.003265,-0.090291,0.035578,0.032956,-0.038992,-0.039414,0.264107,-0.079022,0.010028,0.003463,0.000252,0.011810,0.008444,-0.016708,0.003844,-0.034965,0.001032,0.017719,-0.002115,0.015202,-0.016091,0.040298,-0.029153,0.068359,0.045307,-0.056795,0.034818,0.002213,0.035831,0.015768,-0.011114,0.016769,-0.064026,-0.010068,0.130409,0.024500,-0.040645,0.061469,-0.018252,-0.056627,-0.042361,-0.008431,-0.002132,0.017456,-0.002210,-0.001853,-0.062282,0.003647,-0.076184,0.007454,-0.139373,-0.011464,0.133041,-0.007628,0.049183,-0.069263,-0.013333,-0.055574,0.007300,-0.014279,-0.015848,0.074167,0.040779,-0.003251,0.031394,0.005593,-0.005119,-0.020350,0.003451,-0.039734,0.106961,0.053568,-0.029912,-0.005185,0.011780,-0.021772,-0.026705,0.063208,0.028812,-0.048467,-0.011824,0.028490,0.010534,-0.051810,-0.003393,-0.010468