insert into knowledge_chunks (source_file, content, embedding) values ($kc$india_ncap_overview.txt$kc$, $kc$Agriculture's indirect role in NCAP targets is significant: open field burning of crop residues (especially paddy stubble in Punjab and Haryana after the kharif harvest) is a major seasonal source of PM2.5 and PM10 spikes in the Indo-Gangetic Plain. NCAP funds some crop residue management schemes, though the primary policy lever for stubble burning remains state government compensation and in-situ management mandates.$kc$, '[-0.048597,0.013073,0.024000,-0.025273,0.070336,-0.001532,0.069448,0.025296,-0.058314,-0.017704,0.015947,-0.096919,0.053751,0.058770,0.002151,0.003735,-0.019767,0.041400,0.017941,-0.012578,0.045502,-0.016988,-0.005826,-0.066520,0.037713,0.046345,-0.032917,-0.046253,-0.067113,-0.187231,0.017378,-0.003838,0.030564,-0.034351,-0.028691,-0.018599,0.000362,0.060272,-0.017775,-0.011043,0.046643,0.016136,0.022670,-0.065878,-0.031552,-0.059527,-0.046833,-0.006874,0.010587,-0.062457,0.048051,-0.045749,-0.003427,0.059677,0.025049,-0.021581,0.051456,0.041717,0.048544,0.002789,0.027031,0.057313,-0.248832,0.080447,0.050515,0.001312,0.004290,-0.003888,0.043340,0.023112,-0.055454,0.066688,0.011191,0.029994,0.011888,0.007007,-0.035413,-0.007278,-0.038344,-0.008478,0.006443,0.011862,-0.006695,-0.004988,0.000235,-0.031133,0.002020,-0.083013,0.050721,0.018246,-0.013054,-0.030079,-0.023826,-0.030766,-0.069533,0.017755,0.032515,0.022559,-0.084321,0.236225,-0.047712,-0.009505,-0.018703,-0.009727,0.022551,-0.043450,-0.031681,-0.031981,-0.005319,0.019650,0.026669,0.010451,-0.006026,-0.042299,0.013401,-0.027526,0.048870,-0.012115,-0.070808,-0.036461,0.011163,0.052218,0.048357,-0.004882,0.053750,-0.057099,0.037771,0.116233,0.011702,0.027338,0.052362,-0.102816,-0.045508,-0.044593,0.022486,-0.007897,0.037769,0.000914,-0.000372,0.014952,-0.010085,-0.083341,-0.002111,-0.103452,-0.004380,0.113695,0.002179,0.017940,-0.060120,0.005273,-0.011870,0.067872,-0.005147,0.021405,0