insert into knowledge_chunks (source_file, content, embedding) values ($kc$north_india_seasonal_aqi.txt$kc$, $kc$Agricultural relevance: The AQI spike coincides with the critical Rabi crop establishment period. Evidence suggests:
- Reduced solar radiation reaching fields due to aerosol loading (the "dimming" effect) can slow germination and seedling growth of wheat sown in November.
- Farmers in heavily-burning zones sometimes delay wheat sowing to avoid smoke stress during delicate germination, further compressing the Rabi season.
- In burning zones, soil quality benefits of retaining and incorporating residue (organic matter, microbial activity) are lost, increasing fertiliser requirements over time.$kc$, '[-0.056346,0.036836,0.001195,0.038485,0.065122,0.041308,0.019340,-0.007836,-0.019329,-0.013766,0.029775,-0.070168,0.074458,0.090699,0.010579,0.007109,-0.020059,-0.023200,-0.041160,-0.008654,0.019347,-0.001304,-0.020734,-0.089351,0.046747,0.021869,-0.055423,-0.038962,-0.055053,-0.239007,-0.014474,0.008603,0.053870,-0.033587,0.025550,-0.042500,-0.006603,0.025203,-0.055586,0.031499,0.065207,0.001537,0.014934,-0.073751,-0.060946,-0.061356,-0.016692,-0.003870,0.031830,-0.048483,0.017312,-0.030857,-0.000811,0.024398,0.007646,-0.001490,0.049363,0.075908,0.039748,0.013984,0.001310,0.047868,-0.210812,0.031572,0.071528,-0.005562,-0.029115,-0.010365,0.009166,0.001666,-0.061869,0.058346,-0.035251,0.038790,-0.001980,-0.007197,-0.035791,-0.045045,-0.007304,-0.001191,0.022006,-0.024872,-0.052287,-0.015227,-0.002589,-0.069287,-0.007285,-0.060756,0.054624,0.002746,-0.018042,-0.059436,-0.001406,0.005530,-0.056856,0.001417,-0.008970,-0.043670,-0.069907,0.225692,-0.076299,-0.003682,0.001272,0.011140,0.012549,-0.012105,-0.036066,-0.037367,0.014714,0.043010,-0.002224,0.000139,0.039625,-0.004436,0.034879,-0.026511,0.081708,0.029883,-0.068784,0.055364,0.008861,0.045249,0.041788,-0.018118,0.036483,-0.022509,0.003553,0.109763,-0.009073,0.054403,0.050411,-0.065599,-0.035399,-0.007486,0.010295,0.036252,-0.000800,0.024808,0.024316,-0.031683,-0.024390,-0.060190,0.027029,-0.108850,-0.031443,0.059388,-0.021694,0.021007,-0.035693,-0.038966,-0.015285,0.041468,-0.006942,-0.031712,0.084841,0.074598,-0.002391,0.069426,0.030600,-0.002633,-0.032847,-0.028663,-0.062695,0.099306,0.039361,-0.037840,-0.020695,0.009516,0.002745,-0.041394,0.071308,0.002000,-0.012957,-0.031485,0.055587,-0.020586,-0.024884,0.012919,-0.016015,0.027455,0.089196,-0.019146,-0.020688,0.035809,0.071014,-0.008194,-0.069514,-0.032519,0.050068,0.013706,-0.08755