insert into knowledge_chunks (source_file, content, embedding) values ($kc$north_india_seasonal_aqi.txt$kc$, $kc$Policy responses include financial compensation to farmers for alternative residue management (in-situ mulching, baling for biomass energy), subsidised Happy Seeder machines that sow wheat directly into standing stubble without burning, and legal penalties — though enforcement has been inconsistent given the scale and speed of the post-harvest window.$kc$, '[-0.049074,0.029979,0.010054,-0.010411,0.049581,0.000301,0.001194,0.001380,-0.029805,0.025995,0.026852,-0.074173,-0.004513,0.023016,-0.023213,0.008077,0.020728,0.033282,-0.031086,0.012350,0.045733,-0.041730,-0.044325,-0.101190,0.053990,-0.000204,-0.086844,0.007905,-0.041085,-0.183302,0.016549,-0.043016,0.004277,-0.058539,-0.004435,-0.027463,0.013739,0.028710,-0.037279,0.019954,0.083236,0.008552,-0.022671,-0.042820,-0.031048,-0.051044,0.022727,-0.017787,0.014878,-0.074183,0.015970,-0.019805,0.032638,0.033670,0.019269,-0.002618,0.047169,0.047428,0.035927,0.006954,-0.007863,0.025776,-0.236396,0.067305,0.040036,0.020461,-0.047102,-0.027070,0.025461,0.039955,-0.037178,0.054723,0.023237,0.027658,0.001547,-0.017732,-0.012137,-0.016760,-0.066920,0.004664,-0.006080,-0.056327,-0.065203,0.003307,-0.021270,-0.058877,-0.000177,-0.051649,0.101594,0.030775,-0.029595,-0.021028,-0.025922,0.012080,-0.089306,-0.001855,0.005644,0.020519,-0.070308,0.250350,-0.040858,0.028518,0.020088,-0.044681,0.034072,-0.027921,-0.056352,-0.009473,0.018598,0.052961,0.011600,0.010198,0.016831,-0.024278,0.000997,-0.009633,0.035701,0.019711,0.008160,-0.005649,0.006232,0.046571,-0.006357,-0.023943,0.043115,-0.020220,0.038677,0.107462,-0.001846,0.035874,0.028686,-0.117640,-0.004641,-0.023363,0.007259,0.005685,0.027376,0.035371,0.063350,0.013649,-0.001947,-0.082732,-0.016076,-0.134112,-0.002864,0.097156,-0.005371,0.029168,-0.024956,0.022722,-0.022765,0.071030,-0.014587,-0.024266,0.054356,0.042292,-0.018534,0.025568,0.025803,0.019301,0.001056,0.