insert into knowledge_chunks (source_file, content, embedding) values ($kc$rainfall_variability_climate_change.txt$kc$, $kc$Reference: IPCC AR6 WGI Chapter 8 (Water Cycle), FAO The State of Food and Agriculture 2020, ICAR climate-smart agriculture research

