insert into knowledge_chunks (source_file, content, embedding) values ($kc$who_air_quality_guidelines.txt$kc$, $kc$WHO acknowledges that no safe threshold exists for many of these pollutants — even below these guideline levels, health risks are not zero. The guidelines therefore represent a practical policy target informed by current evidence about disease burden at different concentration levels. Countries are expected to use these as aspirational targets and implement phased national standards according to their economic and technical capacity.$kc$, '[-0.033874,0.030602,0.055764,-0.044149,0.021069,0.020186,0.070806,0.048678,0.003750,0.004502,0.015107,-0.089009,0.003566,0.086260,-0.021395,0.039090,-0.005144,0.007053,-0.035565,0.027208,0.070701,-0.012301,0.011895,-0.076736,0.029658,0.058200,0.005541,-0.041505,-0.041418,-0.199463,-0.029847,-0.030602,-0.007131,-0.037178,-0.038327,-0.048982,0.014634,0.033599,0.001952,0.000629,0.023989,-0.003668,0.004529,-0.066240,-0.067780,-0.043860,-0.050507,0.001411,0.006608,-0.080974,0.014387,0.009795,0.020223,0.019706,0.012482,-0.022739,0.063966,0.031642,0.041056,0.046814,0.045037,0.014899,-0.225324,0.041384,0.049962,0.017314,-0.063903,-0.006452,0.023855,0.018056,-0.010943,-0.007096,0.038654,0.070311,-0.024100,-0.010660,-0.004027,-0.066061,0.011443,-0.001313,0.002785,-0.037141,-0.010094,-0.004303,-0.007718,-0.039308,0.021530,-0.077278,0.021104,-0.012074,-0.025241,-0.032279,-0.014672,-0.006769,-0.055425,-0.005690,0.037234,0.014373,-0.061678,0.204363,-0.048884,0.015753,0.000578,0.005795,0.024118,-0.049575,-0.045275,-0.045219,0.044047,-0.012067,0.011889,-0.028928,0.038944,-0.103603,0.006038,0.049622,-0.007392,0.000461,0.006627,-0.014327,-0.037730,-0.006947,0.052002,-0.011829,0.059377,-0.017099,0.014353,0.105236,0.025994,0.061910,0.062999,-0.074713,-0.034305,0.034369,-0.020435,-0.021577,0.031819,0.016637,-0.004660,0.001610,-0.020647,-0.047878,-0.011736,-0.145123,-0.038288,0.139675,-0.030548,0.035042,-0.068768,0.011499,0.002296,0.068427